mapper.update:
UPDATE reports
SET report_name = #{report.reportName}, report_type = #{report.reportType},
    display_name = #{report.displayName}, description = #{report.description}, sql_query = #{sql}
WHERE report_id = #{report.reportId}

mapper.select:
SELECT rgr.report_group_id FROM report_group_reports rgr WHERE rgr.report_id = #{reportId} AND rgr.report_group_id = #{reportGroupId} AND ( EXISTS (SELECT 1 FROM report_groups rg WHERE rg.report_group_id = rgr.report_group_id AND rg.organizational_type = 0)
OR EXISTS (SELECT 1 FROM organizations_hierarchy oh, report_group_organizations rgo WHERE oh.child_organization_id = #{organizationId} AND rgo.organization_id = oh.parent_organization_id AND rgo.report_group_id = rgr.report_group_id)
) LIMIT 1

mapper.update:
UPDATE report_group_schedules
SET last_execution_date = #{lastExecutionDate},
    next_execution_date = #{nextExecutionDate}
WHERE schedule_id = #{scheduleId}

mapper.delete:
DELETE FROM report_group_organizations
WHERE report_group_id = #{reportGroupId}
    AND organization_id IN (SELECT o.child_organization_id
        FROM organizations_hierarchy o
        WHERE o.parent_organization_id = #{organizationId}
        AND o.level > 0)

mapper.select:
SELECT r.report_id, r.report_name, e.schedule_id, e.row_count, e.execution_date, e.schedule_date,
       e.execution_time, e.metadata, e.analytic_output, e.object_id, e.organization_id, e.error_message
FROM report_execution_history e
    JOIN report_group_schedules rgs ON rgs.schedule_id = e.schedule_id
    JOIN reports r ON r.report_id = e.report_id
WHERE e.execution_date >= #{startDate} AND e.execution_date < #{endDate}
  AND rgs.report_id = #{reportId} AND rgs.report_group_id = #{reportGroupId}
  AND e.schedule_id IS NOT NULL

    AND e.organization_id IS NULL
    AND e.organization_id = #{organizationId}

mapper.delete:
DELETE FROM report_execution_history
WHERE on_demand
AND execution_date < #{expirationDate}
